package lab
import kotlinx.coroutines.*
actual suspend fun platformSynchronization(topic:Int,records:List<String>,emit:(String)->Unit) { when(topic) {
 24 -> { val lock=Any(); var count=0; coroutineScope { List(4) { async(Dispatchers.Default) { repeat(100) { synchronized(lock) { count++ } } } }.awaitAll() }; emit("JVM synchronized counter=$count") }
 25 -> { val map=java.util.concurrent.ConcurrentHashMap<Int,String>(); val list=java.util.Collections.synchronizedList(mutableListOf<String>()); coroutineScope { records.take(20).mapIndexed { i,line -> async(Dispatchers.Default) { map[i]=line; list.add(line) } }.awaitAll() }; emit("ConcurrentHashMap=${map.size}; synchronizedList=${list.size}") }
 26 -> java.util.concurrent.Executors.newSingleThreadExecutor().asCoroutineDispatcher().use { owner -> withContext(owner) { val names=records.take(3).map { async { delay(2); Thread.currentThread().id.toString() } }.awaitAll(); check(names.distinct().size==1); emit("Dedicated dispatcher owner=${names.first()}; suspension retained affinity") } }
} }
actual fun platformTeachingSource(topic:Int):String = if(topic in 24..26) "when(topic) {\n 24 -> { val lock=Any(); var count=0; coroutineScope { List(4) { async(Dispatchers.Default) { repeat(100) { synchronized(lock) { count++ } } } }.awaitAll() }; emit(\"JVM synchronized counter=\$count\") }\n 25 -> { val map=java.util.concurrent.ConcurrentHashMap<Int,String>(); val list=java.util.Collections.synchronizedList(mutableListOf<String>()); coroutineScope { records.take(20).mapIndexed { i,line -> async(Dispatchers.Default) { map[i]=line; list.add(line) } }.awaitAll() }; emit(\"ConcurrentHashMap=\${map.size}; synchronizedList=\${list.size}\") }\n 26 -> java.util.concurrent.Executors.newSingleThreadExecutor().asCoroutineDispatcher().use { owner -> withContext(owner) { val names=records.take(3).map { async { delay(2); Thread.currentThread().id.toString() } }.awaitAll(); check(names.distinct().size==1); emit(\"Dedicated dispatcher owner=\${names.first()}; suspension retained affinity\") } }\n}" else ""
